sqlMap.insert:
INSERT INTO PA_BEN_BASE (PA_BENHS_BASE_SEQ, EMPID, SOCIAL_NO, AVG_SALARY, PAY_SALARY, SOCIAL_STATUS, IMP_TYPE, CREATE_DATE, CREATED_BY, ACTIVITY) (SELECT PA_BENHS_BASE_SEQ.NEXTVAL, T.EMPID, T.SOCIAL_NO, T.AVG_SALARY, T.AVG_SALARY, T.SOCIAL_STATUS, 'N', SYSDATE, #adminID#, 1 FROM PA_BEN_MANAGE T,HR_EMPLOYEE E WHERE TO_CHAR(T.CREATE_DATE, 'yyyymm') = #pabDate# AND T.EMPID = E.EMPID AND T.EMPID NOT IN(SELECT EMPID FROM PA_BEN_BASE B)
(E.DATE_LEFT IS NULL OR (E.DATE_LEFT IS NOT NULL AND E.DATE_LEFT >= TO_DATE(#leftDate:DATE#,'YYYY-MM-DD')))
)
